69	// renderField draws one setting (Rules 120, 132).
70	//
71	// Values are aligned on one column: twenty-nine settings whose values each start
72	// wherever their label happened to end reads as noise, and a cycle field's
73	// select icon makes its prefix two cells wider than a text field's, so the
74	// padding has to be measured on the whole prefix rather than on the label.
75	func (m Model) renderField(f field, focused bool) string {
76		// A checkbox brings its own focus indicator and needs no value column.
77		if f.Kind == kindToggle {
78			if m.isDisabled(f) {
79				return theme.Bg("  ") + theme.RenderCheckboxDisabled(f.Label)
80			}
81			return theme.RenderCheckbox(f.Bool(m.config), f.Label, focused)
82		}
83	
84		indicator := "  "
85		if focused {
86			indicator = theme.IconCircleSmall + " "
87		}
88		prefix := indicator + m.padHead(fieldHead(f)) + " " + theme.IconChevronRight + " "
89	
90		if focused {
91			if f.Kind == kindCycle {
92				return theme.KeyStyle.Render(prefix) + theme.Bg(f.Value(m.config))
93			}
94			return theme.KeyStyle.Render(prefix) + m.input.View()
95		}
96		return theme.Bg(prefix) + theme.Bg(f.Value(m.config))
97	}
