108	// padHead widens a head to the active tab's chevron column.
109	//
110	// Padding here rather than after the chevron aligns both: the chevrons form one
111	// column and the values another. Padding the label alone would leave a cycle
112	// field's chevron two cells right of every other, because its select icon sits
113	// between the two.
114	func (m Model) padHead(head string) string {
115		if w := m.chevronColumn() - lipgloss.Width(head); w > 0 {
116			return head + strings.Repeat(" ", w)
117		}
118		return head
